# Generates addon/WRC/Font.lua from recorder/wrc_recorder/font.py so the
# beacon the addon draws and the glyphs the recorder reads can never drift.
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "recorder"))
from wrc_recorder.font import _RAW  # noqa: E402

out = [
    "-- WRC - WoW Record Combat | Ionity (Pty) Ltd | Author: Johan Wilhelm van Antwerp",
    "-- GENERATED by tools/gen_font.py from recorder/wrc_recorder/font.py. Do not edit.",
    "local _, ns = ...",
    "ns.Font = {",
]
for ch, rows in _RAW.items():
    out.append('    ["%s"] = "%s",' % (ch, rows.replace(" ", "")))
out.append("}")
path = os.path.join(ROOT, "addon", "WRC", "Font.lua")
with open(path, "w", newline="\n") as fh:
    fh.write("\n".join(out) + "\n")
print("wrote", path)
